def load_valid_entries(file_name):
    data_path = files("rlc.data").joinpath(file_name)
    with data_path.open("r", encoding="utf-8") as f:
        return set(line.strip() for line in f if line.strip())


def extract_user_defined_result_names(script_text):
    """
    Parse a Python script to extract user-defined result names from
    the UserDefinedResults() function.

    OrcaFlex requires user-defined results to be returned from a function
    called UserDefinedResults(model) as a tuple/list of dicts, each with
    a "Name" key.

    Args:
        script_text (str): The Python script source code.

    Returns:
        set: A set of user-defined result name strings.
    """
    names = set()
    try:
        tree = ast.parse(script_text)
    except SyntaxError:
        logger.warning(
            "Could not parse user-defined results script (syntax error)."
        )
        return names

    for node in ast.walk(tree):
        if (
            isinstance(node, ast.FunctionDef)
            and node.name == "UserDefinedResults"
        ):
            # Walk the entire function body, not just the return statement,
            # because results may be built in a variable (e.g. base_results)
            # before being returned.
            for child in ast.walk(node):
                if isinstance(child, ast.Dict):
                    for key, value in zip(child.keys, child.values):
                        if (
                            isinstance(key, ast.Constant)
                            and key.value == "Name"
                            and isinstance(value, ast.Constant)
                        ):
                            names.add(value.value)
    return names


def get_user_defined_results(m, config):
    """
    Extract user-defined result names from the OrcaFlex model's external
    function script (embedded or external file).

    Args:
        m: The loaded OrcaFlex model object.
        config (dict): The RLC configuration dictionary.

    Returns:
        set: A set of user-defined result name strings.
    """
    try:
        source = m.general.GetData("UserDefinedResultScriptFileSource", 0)
    except Exception:
        return set()

    if source == "Embedded":
        try:
            script_text = m.general.GetData("UserDefinedResultScript", 0)
        except Exception:
            return set()
        if not script_text:
            return set()
        logger.info("Parsing embedded user-defined results script.")
        return extract_user_defined_result_names(script_text)

    elif source == "External file":
        try:
            script_file = m.general.GetData(
                "UserDefinedResultScriptFileName", 0
            )
        except Exception:
            return set()
        if not script_file:
            return set()

        # Validate that the external script is listed in extra_files
        extra_files = config.get("extra_files", [])
        script_basename = os.path.basename(script_file)
        extra_basenames = [os.path.basename(f) for f in extra_files]
        if script_basename not in extra_basenames:
            logger.error(
                f"User-defined results script '{script_basename}' is not "
                f"listed in extra_files. It must be included for the "
                f"simulation to work."
            )
            return None  # Signal validation failure

        # Read the external script file
        base_dir = os.path.dirname(config.get("base_file", ""))
        script_path = os.path.join(base_dir, script_file)
        if not os.path.isfile(script_path):
            logger.error(
                f"User-defined results script file not found: {script_path}"
            )
            return None
        with open(script_path, "r", encoding="utf-8") as f:
            script_text = f.read()
        logger.info(
            f"Parsing external user-defined results script: {script_file}"
        )
        return extract_user_defined_result_names(script_text)

    return set()


def extract_orcaflex_version(path):
    with open(path, "r", encoding="utf8") as f:
        for line in f:
            if line.startswith("# Program:"):
                match = re.search(
                    r"OrcaFlex\s+([0-9.]+[a-z]?)", line, re.IGNORECASE
                )
                if match:
                    return match.group(1)
    return None


def load_yaml_config(file_path):
    """
    Load and parse the YAML configuration file.

    Args:
        file_path (str): Path to the YAML file.

    Returns:
        dict: Parsed configuration as a dictionary.
    """

    # Load Orcaflex API
    try:
        from OrcFxAPI import FileCreatorVersion, Model

        logger.info("Orcaflex API (OrcFxAPI) loaded")
    except ImportError:
        logger.error("Not able to load OrcFxAPI.")
        return False

    try:
        with open(file_path, "r", encoding="utf-8") as f:
            # Read the YML file and store in config dictionary
            config = yaml.safe_load(f)
            logger.info(f"Configuration loaded from {file_path}")
            base_file = config.get("base_file")

            # Open Orcaflex Base File
            # Need to handle if base file is a yml file or a dat file
            # If *.dat file
            if base_file.endswith(".dat"):
                version = FileCreatorVersion(base_file)
            elif base_file.endswith(".yml"):
                version = extract_orcaflex_version(base_file)
            model = Model(base_file)
            # Add the base file version to the config dictionary
            config["base_file_version"] = version
            logger.info(f"OrcaFlex Base File Version: {version}")
            # Add the time step value and time step method to the config dictionary
            if model.general.ImplicitUseVariableTimeStep == "No":
                base_time_step = model.general.ImplicitConstantTimeStep
                config["base_time_step"] = base_time_step
                config["variable_time_step"] = False
                logger.info(f"Model Constant Time Step: {base_time_step}")
            else:
                max_time_step = model.general.ImplicitVariableMaxTimeStep
                config["base_time_step"] = max_time_step
                config["variable_time_step"] = True
                logger.info(f"Model Max Variable Time Step: {max_time_step}")

            return config
    except yaml.YAMLError as e:
        logger.error(f"Error parsing YAML file: {e}")
        sys.exit(1)


def print_config_aligned(config):
    """Print the configuration in an aligned format.

    Args:
        config (dict): Configuration dictionary.

    Returns:
        None: Prints the configuration to the logger.
    """

    logger.info("Header...")
    for line in config["header"].strip().splitlines():
        logger.info(line)

    logger.info("Configuration Parameters:")
    # Exclude 'header' and 'analysis_criteria' from alignment calculation
    # and printing, as they are handled separately
    keys_to_print = [
        key
        for key in config.keys()
        if key != "header" and key != "analysis_criteria"
    ]
    max_key_length = max(len(str(key)) for key in keys_to_print)

    for key in keys_to_print:
        value = config[key]
        logger.info(f"{key.ljust(max_key_length)} : {value}")

    # Print the analysis criteria in a formatted way
    # Show in a table format
    logger.info("Analysis Criteria:")
    criteria = config.get("analysis_criteria", [])

    # Define headers by searching for keys in all of the dictionaries
    headers = [
        "orcaflex_object_name",
        "orcaflex_object_parameter",
        "orcaflex_object_argument",
        "probability_level",
        "mode",
        "value",
    ]

    table = prettytable.PrettyTable(headers)
    for item in criteria:
        row = [item.get(header, "") for header in headers]
        table.add_row(row)

    print(table)


def validate_header(config):
    header = config.get("header")
    """
    Validate the header of the configuration.

    Args:
        header (str): The header string to validate.

    Returns:
        bool: True if the header is valid, False otherwise.
    """

    logger.debug("Validating Parameter: header")

    if not isinstance(header, str):
        logger.error("Header must be a string.")
        return False
    if not header.strip():
        logger.error("Header cannot be empty.")
        return False
    return True


def validate_base_file(config):
    base_file = config.get("base_file")
    """
    Validate the base file name.

    Args:
        base_file (str): The base file name to validate.

    Returns:
        bool: True if the base file is valid, False otherwise.
    """

    logger.debug("Validating Parameter: base_file")

    if not isinstance(base_file, str):
        logger.error("Base file must be a string.")
        return False
    if not base_file.endswith((".dat", ".yml")):
        logger.error("Base file must have a .dat or .yml extension.")
        return False
    return True


def validate_base_file_version(config):
    """
    Validate the base file version.  This is not in the input file but instead obtained
    from the base_file directly.

    Args:
        config (dict): The configuration dictionary containing the base file version.

    Returns:
        bool: True if the base file version is valid, False otherwise.
    """
    base_file_version = config.get("base_file_version")
    run_method = config.get("run_method")

    if run_method == "hpcflex":
        logger.debug("Validating Parameter: base_file_version")

        latest_acceptable_versions = [
            "11.0g",
            "11.1e",
            "11.2e",
            "11.3g",
            "11.4e",
            "11.5f",
            "11.6b",
        ]

        full_acceptable_versions = []

        # Process each version
        for version in latest_acceptable_versions:
            # Split into major.minor and patch letter
            major_minor = version[:-1]  # e.g., '11.0' from '11.0g'
            patch_letter = version[-1]  # e.g., 'g' from '11.0g'
            # Generate all patch versions for this minor release
            full_acceptable_versions.extend(
                utils.generate_patch_versions(major_minor, patch_letter)
            )

        # Sort the list to ensure versions are in order
        full_acceptable_versions.sort()

        logger.info("Validating base file version for HPC-Flex")

        if base_file_version not in full_acceptable_versions:
            logger.error(
                f"Base file version {base_file_version} is not acceptable."
            )
            return False

        return True

    else:
        return True


def validate_input_file_critical_keys(
    config, ignore_interactive_warnings=False
):
    """
    Check if critical keys in the input file have changed compared to the
    baseline.
    Critical keys:  base_file, calculate_jonswap_gamma,
                    calculate_jonswap_gamma_method, jonswap_gamma

    Args:
        config (dict): Configuration dictionary
        ignore_interactive_warnings (bool): If True, skip interactive dialog

    Returns:
        bool: True if validation passes or user chooses to continue, False
        otherwise
    """
    runs_folder = "runs"
    input_file = config.get("input_file_path")

    if not input_file or not os.path.exists(input_file):
        return True

    input_file_name = os.path.basename(input_file)
    baseline_name = input_file_name + ".original"
    baseline_path = os.path.join(runs_folder, baseline_name)

    if not os.path.exists(runs_folder) or not os.path.exists(baseline_path):
        return True

    # Load baseline config
    try:
        with open(baseline_path, "r", encoding="utf-8") as f:
            baseline_config = yaml.safe_load(f)
    except Exception as e:
        logger.warning(f"Could not load baseline input file: {e}")
        return True

    # Critical keys to check
    critical_keys = [
        "base_file",
        "period_type",
        "calculate_jonswap_gamma",
        "calculate_jonswap_gamma_method",
        "jonswap_gamma",
    ]

    changed_keys = []
    for key in critical_keys:
        # Only compare if key exists in baseline (not added at runtime)
        if key in baseline_config and config.get(key) != baseline_config.get(
            key
        ):
            changed_keys.append(key)

    if not changed_keys:
        logger.info("Input file critical parameters unchanged")
        return True

    # Critical parameters changed
    logger.error(
        f"Critical input file parameters have changed: {', '.join(changed_keys)}"
    )

    return False


def validate_base_file_hash(config, ignore_interactive_warnings=False):
    """
    This function checks to see if the 'runs' folder exists and if there is
    the Orcaflex base file already exists.  It then hashs the Orcaflex base
    file in the current working folder and compares the hash to the hash
    of the Orcaflex base file in the 'runs' folder to determine if the file has
    changed.

    Args:
        config (dict): Configuration dictionary
        ignore_interactive_warnings (bool): If True, skip interactive dialog
    """

    runs_folder = "runs"
    base_file = config.get("base_file")
    base_file_name = os.path.basename(base_file)

    # Check if runs folder exists
    if not os.path.exists(runs_folder):
        # No need to check, runs folder will be created later
        return True

    # Check if base file exists in runs folder
    base_file_in_runs = os.path.join(runs_folder, base_file_name)
    if not os.path.exists(base_file_in_runs):
        # No need to check, file doesn't exist in runs folder
        return True

    # Hash the base file in the current working directory
    current_hash = utils.hash_file(base_file)

    # Hash the base file in the runs folder
    runs_hash = utils.hash_file(base_file_in_runs)

    # Compare the hashes
    if current_hash != runs_hash:
        logger.warning("Base file has changed since last run.")

        # Skip dialog if ignore_interactive_warnings is True
        if ignore_interactive_warnings:
            logger.info(
                "Ignoring interactive warning (--ignore-interactive-warnings flag set)"
            )
            return True

        # Create hidden root window
        root = tk.Tk()
        root.withdraw()

        # Display dialog box
        result = messagebox.askyesno(
            "'runs' Folder Exists and Base File Changed",
            "The 'runs' folder exists and the base file has changed since "
            + "the last run.\n\nDo you want to continue?\n\n"
            + "RESULTS MAY NOT BE CORRECT IF THE BASE FILE HAS CHANGED AND"
            + "PREVIOUS RUNS HAVEN'T BEEN DELETED.",
            icon="warning",
        )

        root.destroy()

        if not result:
            logger.info("User chose to stop due to base file change.")
            return False
        else:
            logger.info("User chose to continue despite base file change.")
            return True

    else:
        logger.info("Base file in runs folder unchanged")

    return True


def validate_hs_start(config):
    hs_start = config.get("hs_start")
    """
    Validate the hs_start value.

    Args:
        hs_start (float): The hs_start value to validate.

    Returns:
        bool: True if the hs_start is valid, False otherwise.
    """

    logger.debug("Validating Parameter: hs_start")

    if not isinstance(hs_start, (int, float)):
        logger.error("'hs_start' must be a numeric value.")
        return False
    if hs_start < 0.1:
        logger.error("'hs_start' must be greater than 0.1 m.")
        return False
    if hs_start > 5:
        logger.warning("'hs_start' seems high.")
    if hs_start > 20:
        logger.warning("'hs_start' must be less than 20 m.")
    return True


def validate_hs_course_step(config):
    hs_course_step = config.get("hs_course_step")
    """
    Validate the hs_course_step value.

    Args:
        hs_course_step (float): The hs_course_step value to validate.

    Returns:
        bool: True if the hs_course_step is valid, False otherwise.
    """

    logger.debug("Validating Parameter: hs_course_step")

    if not isinstance(hs_course_step, (int, float)):
        logger.error("hs_course_step must be a numeric value.")
        return False
    if hs_course_step < 0.1:
        logger.error("hs_course_step must be greater than 0.1 m.")
        return False

    # Check if hs_course_step is a multiple of hs_start
    # This will also identify if hs_course_step is greater than hs_start
    hs_start = config.get("hs_start", 3.5)  # Default to 3.5 if not found
    hs_start_dec = Decimal(str(hs_start))
    hs_course_step_dec = Decimal(str(hs_course_step))
    if hs_start_dec > 0 and hs_start_dec % hs_course_step_dec != 0:
        logger.error(
            "hs_start must be a multiple of hs_course_step. "
            f"Current values: hs_course_step={hs_course_step}, hs_start={hs_start}"
        )
        return False

    return True


def validate_hs_fine_step(config):
    hs_fine_step = config.get("hs_fine_step")
    """
    Validate the hs_fine_step value.

    Args:
        hs_fine_step (float): The hs_fine_step value to validate.

    Returns:
        bool: True if the hs_fine_step is valid, False otherwise.
    """

    logger.debug("Validating Parameter: hs_fine_step")
    hs_course_step = config.get(
        "hs_course_step", 0.0
    )  # Default to 0.0 if not found

    if not isinstance(hs_fine_step, (int, float)):
        logger.error("hs_fine_step must be a numeric value.")
        return False
    if hs_fine_step < 0.1:
        logger.error("hs_fine_step must be greater than or equal to 0.1 m.")
        return False
    if hs_fine_step > hs_course_step:
        logger.error(
            "hs_fine_step must be less than or equal to hs_course step m."
        )
        return False

    # Check if hs_course_step is a multiple of hs_fine_step
    # This will also identify if hs_fine_step is greater than hs_course_step
    hs_course_step_dec = Decimal(str(hs_course_step))
    hs_fine_step_dec = Decimal(str(hs_fine_step))
    if hs_fine_step_dec > 0 and hs_course_step_dec % hs_fine_step_dec != 0:
        logger.error(
            "hs_course_step must be a multiple of hs_fine_step. "
            f"Current values: hs_course_step={hs_course_step}, hs_fine_step={hs_fine_step}"
        )
        return False

    return True


