def validate_calculate_jonswap_gamma_method(config):
    calculate_jonswap_gamma_method = config.get(
        "calculate_jonswap_gamma_method"
    )
    period_type: str = config.get("period_type")
    """
    Validate the calculate_jonswap_gamma_method value.

    Args:
        calculate_jonswap_gamma_method (str): The
        calculate_jonswap_gamma_method value to validate.

    Returns:
        bool: True if the calculate_jonswap_gamma_method is valid, False
        otherwise.
    """

    logger.debug("Validating Parameter: calculate_jonswap_gamma_method")

    valid_jonswap_gamma_methods: list[str] = ["dnv", "of", "pb"]

    if not isinstance(calculate_jonswap_gamma_method, str):
        logger.error("calculate_jonswap_gamma_method must be a string.")
        return False

    if calculate_jonswap_gamma_method not in valid_jonswap_gamma_methods:
        logger.error(
            f"calculate_jonswap_gamma_method must be one of "
            f"{valid_jonswap_gamma_methods}."
        )
        return False

    if calculate_jonswap_gamma_method == "pb" and period_type != "Tp":
        logger.error(
            "period_type must be 'Tp' when calculate_jonswap_gamma_method "
            "is 'pb'."
        )
        return False

    if calculate_jonswap_gamma_method == "of" and period_type != "Tz":
        logger.error(
            "period_type must be 'Tz' when calculate_jonswap_gamma_method is "
            "'of'."
        )
        return False

    if calculate_jonswap_gamma_method == "dnv" and period_type != "Tp":
        logger.error(
            "period_type must be 'Tp' when calculate_jonswap_gamma_method is "
            "'dnv'."
        )
        return False
    return True


