def validate_t_end(config):
    t_end = config.get("t_end")
    t_start = config.get("t_start")
    """
    Validate the t_end value.

    Args:
        t_end (float): The t_end value to validate.

    Returns:
        bool: True if the t_end is valid, False otherwise.
    """

    logger.debug("Validating Parameter: t_end")

    if not isinstance(t_end, (int, float)):
        logger.error("t_end must be a numeric value.")
        return False
    if t_end <= 1:
        logger.error("t_end must be greater than 1.")
        return False
    if t_end > 30:
        logger.error("t_end must be less than 30.")
        return False
    if t_start > t_end:
        logger.error("t_start must be less than t_end.")
        return False
    return True


