def validate_automatic_post_calc(config):
    auto_post_calc = config.get("automatic_post_calc")
    """
    Validate the automatic_post_calc value.

    Args:
        automatic_post_calc (bool): The automatic_post_calc value to validate.

    Returns:
        bool: True if the automatic_post_calc is valid, False otherwise.
    """
    logger.debug("Validating Parameter: automatic_post_calc")

    if not isinstance(auto_post_calc, bool):
        logger.error("automatic_post_calc must be a boolean value.")
        return False

    # If automatic_post_calc is False, ensure the file name referenced in the Orcaflex File
    # is correct.

    # Load Orcaflex API
    try:
        from OrcFxAPI import DLLError as ofDLLError
        from OrcFxAPI import Model as ofModel
        from OrcFxAPI import stLicensingError as ofstLicensingError

        logger.info("Orcaflex API (OrcFxAPI) loaded")
    except ImportError:
        logger.error("Not able to load OrcFxAPI.")
        return False

    # Load the OF model
    logger.info("Reading name of post calculation actions scripts from model.")
    while True:
        try:
            m = ofModel(config.get("base_file"))
            break
        except ofDLLError as err:
            if not err.status == ofstLicensingError:
                raise
            else:
                logger.info("Trying to get an Orcaflex license...")
                time.sleep(3)

    # Ensure there is at least one post calc action file referenced
    number_post_calc_actions = m.general.GetData(
        "NumberOfPostCalculationActions", 0
    )
    if number_post_calc_actions == 0:
        logger.error(
            "No post calculation action set up in the model."
            "At least one action is required."
        )
        return False

    if auto_post_calc:
        logger.debug("Checking to see if auto post calc files are present.")
        # Check if post calc action name file name is included in the post calc actions.
        for i in range(number_post_calc_actions):  # type: ignore
            m.general.SelectedPostCalculationAction = m.general.GetData(
                "PostCalculationActionName", i
            )
            post_calc_script_name = m.general.GetData(
                "PostCalculationActionScriptFileName", 0
            )

            # If using Auto Post Calc Actions
            if post_calc_script_name == "auto_post_calc_action.py":
                logger.info("Automatic Post Calc Action Specified...")
                break

            # If this is the last item and it wasn't found, then return error.
            if i == number_post_calc_actions - 1:  # type: ignore
                logger.error(
                    "The post calculation action file referenced in the model "
                    "is not in the folder."
                )
                logger.error(
                    "Automatic Post Calc Action file 'auto_post_calc_action.py' not found..."
                )
                return False

    else:
        logger.debug("Checking to see if post calc files are present.")
        # Ensure that post calc action file is in the folder
        for i in range(number_post_calc_actions):  # type: ignore
            post_calc_script_name = m.general.GetData(
                "PostCalculationActionScriptFileName", 0
            )
            if not os.path.exists(post_calc_script_name):  # type: ignore
                logger.error(
                    "The post calculation action file referenced in the model "
                    "is not in the folder."
                )
                return False

    return True


