def validate_analysis_criteria(config):
    """
    Validate the analysis_criteria value.

    Args:
        analysis_criteria (dict): The analysis_criteria value to validate.

    Returns:
        bool: True if the analysis_criteria is valid, False otherwise.
    """
    logger.debug("Validating Parameter: analysis_criteria")

    def validate_orcaflex_object_name(orcaflex_object_name, m):
        """
        Validate the orcaflex_object_name value.

        Args:
            orcaflex_object_name (str): The orcaflex_object_name value to validate.

        Returns:
            bool: True if the orcaflex_object_name is valid, False otherwise.
        """
        # Check that it is a string
        if not isinstance(orcaflex_object_name, str):
            logger.error("orcaflex_object_name must be a string.")
            return False

        # Check that the name exists in the model
        if orcaflex_object_name not in m:
            logger.error(f"'{orcaflex_object_name}' doesn't exist in model.")
            return False

        # Check that the object type is an acceptable type:
        acceptable_types = [
            "Line",
            "6D buoy",
            "Link",
            "Winch",
            "Constraint",
            "Shape",
        ]
        obj_type = m[orcaflex_object_name].typeName
        if obj_type not in acceptable_types:
            logger.error(
                f"{obj_type} is not an acceptable type. "
                f"Must be one of {acceptable_types}"
            )
            return False

        return True

    def validate_orcaflex_object_parameter(
        m, orcaflex_object_name, orcaflex_object_parameter, user_defined_names
    ):
        """
        Validate the orcaflex_object_parameter value.

        Args:
            orcaflex_object_parameter (str): The orcaflex_object_parameter value to validate.
            user_defined_names (set): Set of valid user-defined result names.

        Returns:
            bool: True if the orcaflex_object_parameter is valid, False otherwise.
        """
        if not isinstance(orcaflex_object_parameter, str):
            logger.error("orcaflex_object_parameter must be a string.")
            return False

        # Check if it is a user-defined result
        if orcaflex_object_parameter in user_defined_names:
            return True

        # Get Orcaflex object type:
        obj_type = m[orcaflex_object_name].typeName
        if obj_type == "Line":
            valid_parameters = load_valid_entries("valid_line_results.txt")
        elif obj_type == "6D buoy":
            valid_parameters = load_valid_entries("valid_6dbuoy_results.txt")
        elif obj_type == "Link":
            valid_parameters = load_valid_entries("valid_link_results.txt")
        elif obj_type == "Winch":
            valid_parameters = load_valid_entries("valid_winch_results.txt")
        elif obj_type == "Constraint":
            valid_parameters = load_valid_entries(
                "valid_constraint_results.txt"
            )
        elif obj_type == "Shape":
            valid_parameters = load_valid_entries("valid_shape_results.txt")
        else:
            valid_parameters = []

        # Check if the parameter is a valid parameter per the valid_X_results.txt files in data.
        if orcaflex_object_parameter not in valid_parameters:
            logger.error(
                f"'{orcaflex_object_parameter}' is not a valid result parameter for a {obj_type} element"
            )
            return False

        return True

    def validate_orcaflex_object_argument(
        m, orcaflex_object_name, orcaflex_object_argument
    ):
        """
        Validate the orcaflex_object_argument value.

        Args:
            orcaflex_object_argument (str or float): The orcaflex_object_argument value to validate.

        Returns:
            bool: True if the orcaflex_object_argument is valid, False otherwise.
        """

        if isinstance(orcaflex_object_argument, (int, float)):
            # Value is a float, need to make sure it is less than the length of the line
            if (
                orcaflex_object_argument
                > m[orcaflex_object_name].cumulativeLength[-1]
            ):
                logger.error(
                    f"'The arc length for {orcaflex_object_argument}' is larger than the total line length."
                )
                return False

            return True  # Accept any float

        if isinstance(orcaflex_object_argument, str):
            valid_strings = {"End A", "End B", "Range"}
            return orcaflex_object_argument.strip() in valid_strings

        logger.error(
            f"The argument for {orcaflex_object_argument} is not an string, integer or float."
        )
        return False  # Invalid type

    def validate_probability_level(probability_level):
        """
        Validate the probability_level value.

        Args:
            probability_level (float): The probability_level value to validate.

        Returns:
            bool: True if the probability_level is valid, False otherwise.
        """
        if not isinstance(probability_level, (int, float)):
            logger.error("probability_level must be a numeric value.")
            return False
        if not (0 <= probability_level <= 1):
            logger.error("probability_level must be between 0 and 1.")
            return False
        return True

    def validate_mode(mode):
        """
        Validate the mode value.

        Args:
            mode (str): The mode value to validate.

        Returns:
            bool: True if the mode is valid, False otherwise.
        """
        if not isinstance(mode, str):
            logger.error("mode must be a string.")
            return False
        valid_modes = ["max", "min", "abs"]
        if mode not in valid_modes:
            logger.error(f"mode must be one of {valid_modes}.")
            return False
        return True

    def validate_value(value):
        """
        Validate the value.

        Args:
            value (float): The value to validate.

        Returns:
            bool: True if the value is valid, False otherwise.
        """
        if not isinstance(value, (int, float)):
            logger.error("Acceptance value must be a numeric value.")
            return False
        return True

    # analysis_criteria is a list of dictionaries, each with keys:
    analysis_criteria = config.get("analysis_criteria")

    # Load the OrcaFlex model:
    # Load Orcaflex API
    try:
        from OrcFxAPI import DLLError as ofDLLError
        from OrcFxAPI import Model as ofModel
        from OrcFxAPI import stLicensingError as ofstLicensingError

        logger.info("Orcaflex API (OrcFxAPI) loaded")
    except ImportError:
        logger.error("Not able to load OrcFxAPI.")
        return False

    # Load the OF model
    while True:
        try:
            m = ofModel(config.get("base_file"))
            break
        except ofDLLError as err:
            if not err.status == ofstLicensingError:
                raise
            else:
                logger.info("Trying to get an Orcaflex license...")
                time.sleep(3)

    # Extract user-defined result names from the model
    user_defined_names = get_user_defined_results(m, config)
    if user_defined_names is None:
        # None signals a validation error (e.g. external script not in extra_files)
        return False
    if user_defined_names:
        logger.info(
            f"User-defined results found: {', '.join(sorted(user_defined_names))}"
        )

    if not isinstance(analysis_criteria, list):
        logger.error("analysis_criteria must be a list.")
        return False

    # Each criteria in analysis_criteria should be a dictionary with specific and optional keys
    required_keys = [
        "orcaflex_object_name",
        "orcaflex_object_parameter",
        "probability_level",
        "mode",
        "value",
    ]
    optional_keys = ["orcaflex_object_argument"]

    # Track duplicates: key = (name, parameter, argument, probability_level, mode)
    # Use dict to also report indices of the duplicate entries
    seen_keys: dict[tuple, int] = {}

    for i, criteria in enumerate(analysis_criteria):
        if not isinstance(criteria, dict):
            logger.error(
                "Each item in analysis_criteria must be a dictionary."
            )
            return False

        # Check for required keys
        for key in required_keys:
            if key not in criteria:
                logger.error(
                    f"Missing required key '{key}' in analysis_criteria item: {criteria}"
                )
                return False

        # Check for optional keys
        for key in criteria.keys():
            if key not in required_keys and key not in optional_keys:
                logger.error(
                    f"Invalid key '{key}' found in analysis_criteria item: {criteria}"
                )
                return False

        # Validate each key using its corresponding validation function
        # Check orcaflex_object_name
        if "orcaflex_object_name" in criteria:
            # Checks to make sure it's a string and that the object exists.
            if not validate_orcaflex_object_name(
                criteria["orcaflex_object_name"], m
            ):
                return False

        # Check orcaflex_object_parameter
        if "orcaflex_object_parameter" in criteria:
            if not validate_orcaflex_object_parameter(
                m,
                criteria["orcaflex_object_name"],
                criteria["orcaflex_object_parameter"],
                user_defined_names,
            ):
                return False

        obj_type = m[criteria["orcaflex_object_name"]].typeName
        if "orcaflex_object_argument" in criteria:
            if obj_type == "Line":
                if not validate_orcaflex_object_argument(
                    m,
                    criteria["orcaflex_object_name"],
                    criteria["orcaflex_object_argument"],
                ):
                    return False
            else:
                logger.info(
                    f"Object {criteria['orcaflex_object_name']} is of type: {obj_type}"
                )
                logger.error(
                    f"A orcaflex_object_argument has been specified for {criteria['orcaflex_object_name']}.  This object does not require an argument"
                )
                return False
        else:
            if obj_type == "Line":
                logger.error(
                    f"Object {criteria['orcaflex_object_name']} is a Line Element and requires a positional argument."
                )
                return False

        if "probability_level" in criteria:
            if not validate_probability_level(criteria["probability_level"]):
                return False

        if "mode" in criteria:
            if not validate_mode(criteria["mode"]):
                return False

        if "value" in criteria:
            if not validate_value(criteria["value"]):
                return False

        # Build the uniqueness key (treat missing optional argument as None)
        arg = criteria.get("orcaflex_object_argument", None)
        key = (
            criteria["orcaflex_object_name"],
            criteria["orcaflex_object_parameter"],
            arg,
            float(criteria["probability_level"]),  # normalize numeric
            criteria["mode"],
        )

        # Check for duplicates
        if key in seen_keys:
            prev_i = seen_keys[key]
            logger.error(
                "Duplicate analysis_criteria detected: entries %d and %d have the same "
                "(orcaflex_object_name, orcaflex_object_parameter, orcaflex_object_argument, "
                "probability_level, mode) = %s. Only one criterion is allowed for a given "
                "combination, even if 'value' differs.",
                prev_i,
                i,
                key,
            )
            return False

        seen_keys[key] = i

    return True


def validate_input(config, ignore_interactive_warnings=False):
    """
    Validate the input data for the RLC analysis.

    Args:
        config (dict): The input data to validate.
        ignore_interactive_warnings (bool): If True, skip interactive dialogs

    Returns:
        bool: True if the input is valid, False otherwise.
    """

    # Define default values
    default_values = {
        "hs_start": 3.5,
        "hs_course_step": 0.5,
        "hs_fine_step": config.get("hs_course_step"),
        "hs_min": 0.25,
        "period_type": "Tp",
        "calculate_jonswap_gamma": True,
        "calculate_jonswap_gamma_method": "of",
        "calculate_min_period": True,
        "jonswap_gamma": 1.0,
        "t_end": 18.0,
        "t_start": 1.0,
        "t_step": 1.0,
        "t_step2": 2.0,
        "t_step_change": 8.0,
        "t_extra": [],
        "wave_dirs": [165, 180, 195],
        "min_seeds": 50,
        "seed_random_generator": 12343,
        "alpha_factor": 1.0,
        "run_method": "dof",
        "extra_files": [],
        "ks_test_criteria": 0.05,
        "ad_test_criteria": 0.05,
        "force_skip_sim_file_save": True,
        "automatic_post_calc": True,
        "num_bootstraps": 10000,
        "conf_interval": 0.95,
        "max_bisections": 0,
        "email_on_failure": False,
        "email_on_loop": False,
        "email_on_finish": False,
        "zero_wave_timeout": 600,
        "path_orcfx_dll": r"",
    }

    # Ensure config is a dictionary
    if not isinstance(config, dict):
        logger.error("Input configuration must be a dictionary.")
        return False

    # Map keys to their validation functions
    validation_functions = {
        "header": validate_header,
        "base_file": validate_base_file,
        "base_file_hash": validate_base_file_hash,
        "input_file_critical_keys": validate_input_file_critical_keys,
        "hs_start": validate_hs_start,
        "hs_course_step": validate_hs_course_step,
        "hs_fine_step": validate_hs_fine_step,
        "hs_min": validate_hs_min,
        "period_type": validate_period_type,
        "calculate_jonswap_gamma": validate_calculate_jonswap_gamma,
        "calculate_jonswap_gamma_method": validate_calculate_jonswap_gamma_method,
        "calculate_min_period": validate_calculate_min_period,
        "jonswap_gamma": validate_jonswap_gamma,
        "t_end": validate_t_end,
        "t_start": validate_t_start,
        "t_step": validate_t_step,
        "t_step2": validate_t_step2,
        "t_step_change": validate_t_step_change,
        "t_extra": validate_t_extra,
        "wave_dirs": validate_wave_dirs,
        "min_seeds": validate_min_seeds,
        "seed_random_generator": validate_seed_random_generator,
        "alpha_factor": validate_alpha_factor,
        "run_method": validate_run_method,
        "extra_files": validate_extra_files,
        "ks_test_criteria": validate_ks_test_criteria,
        "ad_test_criteria": validate_ad_test_criteria,
        "force_skip_sim_file_save": validate_force_skip_sim_file_save,
        "automatic_post_calc": validate_automatic_post_calc,
        "num_bootstraps": validate_num_bootstraps,
        "conf_interval": validate_conf_interval,
        "max_bisections": validate_max_bisections,
        "analysis_criteria": validate_analysis_criteria,
        "path_orcfx_dll": validate_path_orcfx_dll,
        "base_file_version": validate_base_file_version,
        "email_on_failure": validate_email_on_failure,
        "email_on_loop": validate_email_on_loop,
        "email_on_finish": validate_email_on_finish,
        "zero_wave_timeout": validate_zero_wave_timeout,
    }

    # Check to see if any keys are not a valid key.  If an invalid key is found, log an error and return False.
    valid_keys = set(validation_functions.keys()).union(
        set(default_values.keys())
    )
    # Adding keys to valid_keys that are added by the script (not in the input yml file)
    valid_keys.add("base_time_step")
    valid_keys.add("variable_time_step")
    valid_keys.add("input_file_path")
    for key in config.keys():
        if key not in valid_keys:
            logger.error(f"Invalid key found in input configuration: {key}")
            return False

    # Check for required keys
    required_keys = ["header", "base_file", "analysis_criteria"]
    for key in required_keys:
        if key not in config:
            logger.error(f"Input file must contain a '{key}' key.")
            return False

    # Populate missing keys with default values
    for key, default_value in default_values.items():
        if key not in config:
            config[key] = default_value
            logger.warning(
                f"Key '{key}' is missing from the input configuration. Using default value: {default_value}"
            )

    # Validate each key using its corresponding validation function
    logger.info("Validating input configuration...")
    for key, validate_func in validation_functions.items():
        if key in ["base_file_hash", "input_file_critical_keys"]:
            # Pass ignore_interactive_warnings to these validations
            if not validate_func(config, ignore_interactive_warnings):
                logger.error(f"Validation failed for key: {key}")
                return False
        else:
            if not validate_func(config):
                logger.error(f"Validation failed for key: {key}")
                return False

    return True


def import_input_file(input_file, ignore_interactive_warnings=False):
    """Import the input file and print its contents.
    This function expects the input file to be passed as a command line argument.
    It loads the YAML configuration and prints it in an aligned format.

    Args:
        input_file (str): Path to the input YAML file.
        ignore_interactive_warnings (bool): If True, skip interactive dialogs

    Returns:
        dict: Configuration dictionary
    """

    config = load_yaml_config(input_file)

    # Store input file path in config for later use
    config["input_file_path"] = input_file

    if not validate_input(config, ignore_interactive_warnings):
        msg = "Invalid input configuration. Please check the input file."
        logger.error(msg)

        # Get flag for email_on_failure
        try:
            # Catches case where email_on_failure not properly defined
            config.get("email_on_failure")
            if config.get("email_on_failure"):
                notifier = get_notifier()
                notifier.error(msg)
        except Exception as e:
            logger.error(f"Error sending email: {e}")
        sys.exit(1)

    print_config_aligned(config)

    # Add your input file import code here
    logger.info("Input file imported successfully.")

    return config
